// All backend calls of the Categories page. Docs: ../backend/doc/week1/categories.txt
import api from "../../services/api";

// Only the documented fields. `code` is generated by the server and never sent.
function toCategoryBody(form) {
  return {
    name: form.name.trim(),
  };
}

export async function getCategories() {
  const response = await api.get("/categories");
  return response.data.data;
}

export async function createCategory(form) {
  const response = await api.post("/categories", toCategoryBody(form));
  return response.data.data;
}

export async function updateCategory(id, form) {
  const response = await api.patch(`/categories/${id}`, toCategoryBody(form));
  return response.data.data;
}

export async function deleteCategory(id) {
  await api.delete(`/categories/${id}`);
}
